    const gasCol = col('Gas', 30004865, [ext({ pin: { id: 7 }, extractor: { product: 2268, heads: 8 } })]);
    const barCol = col('Barren', 30004865, [ext({ pin: { id: 8 } })]);
    const live1 = learnedRates([{ colonies: [barCol, gasCol] }], ix, 'formula');
