  const big = { ix, planets: bigPlanets, char: { charId: OWNER, name: 'Owner', planets: 5, ccLevel: 4, alpha: false }, others: [second, unread],
    rateOf: () => rate(), sell: sellBy(bigPrice), buy: noBuy, programHours: 72 };

