      char: { charId: 1, name: 'Owner', planets: 2, ccLevel: 4, alpha: false }, others: [],
      rateOf: (t) => (t === 'Barren' ? rate({ perHour: 13_930, heads: 10 }) : t === 'Lava' ? lava : null),
