  const raw = [b(30, 25895, 60003760, -1, -1, 10, 20), b(10, 25895, 1046664001931, -2, 40, 10, 20), b(20, 804, 1_044_519_007_308, 3, -1, 0, 0)];
  const doc = T.toBlueprintsDoc(raw, { 1044519007308: 'Blueprints', 99: 'gone' });
