  const doc3 = K.copyContractsOf(doc2, list.filter((c) => c.id !== 503), items, {}, ME, '2026-11-05T12:00:00Z');
  const doc4 = K.copyContractsOf(doc3, list.filter((c) => c.id !== 503), items, {}, ME, '2026-11-06T12:00:00Z');
